//! Generated crate containing the image ID and ELF binary of the build guest.
#[rustfmt::skip]
mod methods;
pub use methods::*;

#[cfg(test)]
mod tests {
    use super::*;
    use dcap_quote_verifier::verifier::QuoteVerificationOutput;
    use risc0_zkvm::{ExecutorEnv, LocalProver, Prover, ProverOpts, VerifierContext};

    #[test]
    fn test_prove() {
        let quote = hex::decode("").unwrap();
let collateral = hex::decode("").unwrap();
        let current_time = 1758881547u64;

        let env = ExecutorEnv::builder()
            .write(&(quote, collateral, current_time))
            .unwrap()
            .build()
            .unwrap();

        // Remove dev mode for real proof generation
        std::env::remove_var("RISC0_DEV_MODE");
        println!("Starting REAL proof generation (no dev mode)...");
        let prover = LocalProver::new("production");
        println!("Calling prover.prove_with_ctx...");
        let res = prover.prove_with_ctx(
            env,
            &VerifierContext::default(),
            DCAP_QUOTE_VERIFIER_ELF,
            &ProverOpts::groth16(),
        );
        println!("Proof generation completed!");
        assert!(res.is_ok(), "Prover failed: {:?}", res.err().unwrap());
        let proof_result = res.unwrap();
        println!("proving stats: {:?}", proof_result.stats);

        // Save the proof journal bytes to disk
        std::fs::write("tdx_proof_journal.bin", &proof_result.receipt.journal.bytes).expect("Failed to write journal to file");
        println!("Saved proof journal to: tdx_proof_journal.bin ({} bytes)", proof_result.receipt.journal.bytes.len());

        // Extract and save the actual seal bytes with proper RISC Zero format (if available)
        match &proof_result.receipt.inner {
            risc0_zkvm::InnerReceipt::Groth16(groth16_receipt) => {
                // RISC Zero expects seal format: [4-byte selector][actual seal bytes]
                let selector = &groth16_receipt.verifier_parameters.as_bytes()[..4];
                let mut full_seal = Vec::with_capacity(selector.len() + groth16_receipt.seal.len());
                full_seal.extend_from_slice(selector);
                full_seal.extend_from_slice(&groth16_receipt.seal);
                
                // Save full seal (selector + seal) as binary file
                std::fs::write("tdx_proof_seal.bin", &full_seal).expect("Failed to write seal to file");
                println!("Saved proof seal to: tdx_proof_seal.bin ({} bytes)", full_seal.len());
                
                // Save full seal as hex string for easy copy-paste
                let seal_hex = hex::encode(&full_seal);
                std::fs::write("tdx_proof_seal.hex", &seal_hex).expect("Failed to write seal hex to file");
                println!("Saved proof seal as hex to: tdx_proof_seal.hex");
                println!("Seal (hex): {}", seal_hex);
                
                // Also save raw seal without selector for debugging
                let raw_seal_hex = hex::encode(&groth16_receipt.seal);
                std::fs::write("tdx_proof_seal_raw.hex", &raw_seal_hex).expect("Failed to write raw seal hex");
                println!("Raw seal without selector (hex): {}", raw_seal_hex);
                println!("Selector (hex): {}", hex::encode(selector));
            },
            _ => {
                println!("WARNING: Not a Groth16 receipt (likely dev mode) - no real seal generated");
                println!("For real on-chain verification, run without RISC0_DEV_MODE");
                
                // Create a placeholder seal file for testing (with fake selector)
                let placeholder_selector = vec![0xFFu8; 4]; // Dev mode selector
                let placeholder_seal_raw = vec![0u8; 256]; // 256 bytes of zeros 
                let mut placeholder_seal = Vec::with_capacity(4 + 256);
                placeholder_seal.extend_from_slice(&placeholder_selector);
                placeholder_seal.extend_from_slice(&placeholder_seal_raw);
                
                std::fs::write("tdx_proof_seal.bin", &placeholder_seal).expect("Failed to write placeholder seal");
                let seal_hex = hex::encode(&placeholder_seal);
                std::fs::write("tdx_proof_seal.hex", &seal_hex).expect("Failed to write placeholder seal hex");
                println!("Created placeholder seal for testing (will not work on-chain)");
            }
        };

        // Save the entire receipt as hex for inspection
        let receipt_hex = format!("{:#?}", proof_result.receipt);
        std::fs::write("tdx_proof_receipt_debug.txt", &receipt_hex).expect("Failed to write receipt debug to file");
        println!("Saved proof receipt debug to: tdx_proof_receipt_debug.txt");

        let verification_output = QuoteVerificationOutput::from_bytes(&proof_result.receipt.journal.bytes);
        assert!(verification_output.is_ok(), "Verifier failed: {:?}", verification_output.err().unwrap());
        let verification_result = verification_output.unwrap();
        
        // Save the verification output as debug format
        let verification_debug = format!("{:#?}", verification_result);
        std::fs::write("tdx_verification_output.txt", &verification_debug).expect("Failed to write verification output to file");
        println!("Saved verification output to: tdx_verification_output.txt");
        
        println!("verifier output: {:?}", verification_result);
    }
}
